# 动物类
class Animal: 
    def __init__(self, name, color):
        self.name = name
        self.color = color

# 猫类，继承动物类
class Cat(Animal):
    def purr(self):
        print("Purr...")

# 狗类，继承动物类
class Dog(Animal):
    def bark(self):
        print("Woof!")

fido = Dog("Fido", "brown")
print(fido.color)
fido.bark()

class Wolf: 
    def __init__(self, name, color):
        self.name = name
        self.color = color

    def bark(self):
        print("Grr...")

class Dog(Wolf):

    # 覆盖类父类的bark 方法
    def bark(self):
        print("Woof")

husky = Dog("Max", "grey")
husky.bark()

